            label="Log out"
          >
            Log Out
          </storybook-button>
        </div>
      } @else {
        <div>
          <storybook-button
            size="small"
            class="margin-left"
            (onClick)="onLogin.emit($event)"
            label="Log in"
          >
            Log in
          </storybook-button>

          <storybook-button
            size="small"
            [primary]="true"
            class="margin-left"
            (onClick)="onCreateAccount.emit($event)"
            label="Sign up"
          >
            Sign Up
          </storybook-button>
        </div>
      }
    </div>
  </div>
</header>
`,
  styleUrls: ['./header.css'],
})
