})
export class InputField {
  @Input() label = '';
  @Input() placeholder = '';
  @Input() value = '';
  @Input() disabled = false;
  @Input() error = '';
  @Input() required = false;
  @Input() readonly = false;
@Input() size: 'sm' | 'md' = 'md';

  isFocused = false;
}

import { CommonModule } from '@angular/common';
import { Component, ElementRef, HostListener, Input, OnInit, OnChanges, SimpleChanges, Output, EventEmitter } from '@angular/core';
import { Checkbox } from '../checkbox/checkbox';
import { Tooltip } from '../tooltip/tooltip';

@Component({
  selector: 'app-multi-select-dropdown',
  imports: [CommonModule, Checkbox,Tooltip],
  templateUrl: './multi-select-dropdown.html',
  styleUrl: './multi-select-dropdown.scss',
})
export class MultiSelectDropdown implements OnInit, OnChanges {
  constructor(private element: ElementRef) { }

  @Input() label = '';
  @Input() options: string[] = [];
  @Input() disabled = false;
  @Input() readonly = false;
  @Input() error = '';
  @Input() required = true;
  @Input() selected: string[] = [];
  filteredOptions: string[] = [];

  @Input() placeholder = 'Select Items';
  @Input() dropdownIcon: string = 'assets/icons/dropdown.svg';
  @Input() mode: 'dropdown' | 'search' = 'dropdown';
@Output() selectedChange = new EventEmitter<string[]>();
  isOpen = false;
  isFocused = false;
  truncate(value: string, limit = 10): string {
    return value.length > limit
      ? value.slice(0, limit) + '…'
      : value;
  }
  ngOnInit(): void {
    this.filteredOptions = [...this.options];
  }
  handleClick(): void {
    if (this.disabled || this.readonly) return;
    if (this.mode === 'dropdown') {
      this.isOpen = !this.isOpen;
    }

    if (this.mode === 'search') {
      this.isOpen = true;
    }

    this.isFocused = this.isOpen;
    this.filteredOptions = [...this.options];
  }
toggleSelect(item: string) {
  const updated = this.selected.includes(item)
    ? this.selected.filter(i => i !== item)
    : [...this.selected, item];

  this.selected = updated;
  this.selectedChange.emit(updated);
}

removeSelected(item: string) {
  this.selected = this.selected.filter(i => i !== item);
  this.selectedChange.emit(this.selected);
}

  filterOptions(event: Event): void {
    const value = (event.target as HTMLInputElement).value.toLowerCase();
    this.filteredOptions = this.options.filter(opt =>
      opt.toLowerCase().includes(value)
    );
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent): void {
    const clickedInside = this.element.nativeElement.contains(event.target);

    if (!clickedInside && this.isOpen) {
      this.isOpen = false;
      this.isFocused = false;
    }
  }
  ngOnChanges(changes: SimpleChanges): void {
  if (changes['options']) {
    this.filteredOptions = [...this.options];
  }

  if (changes['selected']) {
    this.selected = [...this.selected];
  }
}

}

import { Component, Input } from '@angular/core';
export interface NavChild {
  label: string;
  icon?: string;
}

export interface NavItem {
  icon: string;
  label: string;
  children?: NavChild[];
}
@Component({
  selector: 'app-navigation',
  imports: [],
  templateUrl: './navigation.html',
  styleUrl: './navigation.scss',
})
export class Navigation {
  @Input() expanded = false;
  @Input() showParentIcons = true;
  @Input() showChildIcons = true;
  @Input() showLogo = true;
  @Input() activeIndex: number | null = null;
  @Input() openIndex: number | null = null;
  @Input() useSlider = false;
  hoveredIndex: number | null = null;
  activeChild: { parent: number; index: number } | null = null;

  navItems: NavItem[] = [];
  hoverY = 0;
  panelTop: number = 0;
  onHover(index: number, event: MouseEvent) {
    const target = event.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    this.panelTop = rect.top;
    this.hoveredIndex = index;

    this.hoverY = rect.top + rect.height / 2;
  }
  onHoverChildClick(parentIndex: number, childIndex: number) {
    this.expanded = true;
    this.activeIndex = parentIndex;
    this.openIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex,
    };
    this.hoveredIndex = null;
  }

  onParentClick(index: number, hasChildren: boolean) {

    if (this.openIndex === index) {
      this.openIndex = null;
      this.activeChild = null;
      return;
    }

    this.activeIndex = index;

    if (hasChildren) {
      this.openIndex = index;

      this.activeChild = {
        parent: index,
        index: 0
      };
    } else {
      this.openIndex = null;
      this.activeChild = null;
    }
  }


  toggle() {
    this.expanded = !this.expanded;

    if (!this.expanded) {
      this.activeIndex = null;
      this.openIndex = null;
      this.activeChild = null;
    }
  }

  toggleItem(index: number) {
    this.activeIndex = this.activeIndex === index ? null : index;
    this.activeChild = null;
  }

  selectChild(parentIndex: number, childIndex: number) {
    this.activeIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex
    };
  }
}

import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HeaderComponent } from '../header/header.component';
import { User } from '../../models/user';

@Component({
  selector: 'storybook-page',
  standalone: true,
  imports: [CommonModule, HeaderComponent],
  template: `<article>
  <storybook-header
    [user]="user"
    (onLogout)="doLogout()"
    (onLogin)="doLogin()"
    (onCreateAccount)="doCreateAccount()"
  ></storybook-header>
  <section class="storybook-page">
    <h2>Pages in Storybook</h2>
    <p>
      We recommend building UIs with a
      <a href="https://componentdriven.org" target="_blank" rel="noopener noreferrer">
        <strong>component-driven</strong>
      </a>
      process starting with atomic components and ending with pages.
    </p>
    <p>
      Render pages with mock data. This makes it easy to build and review page states without
      needing to navigate to them in your app. Here are some handy patterns for managing page data
      in Storybook:
    </p>
    <ul>
      <li>
        Use a higher-level connected component. Storybook helps you compose such data from the
        "args" of child component stories
      </li>
      <li>
        Assemble data in the page component from your services. You can mock these services out
        using Storybook.
      </li>
    </ul>
    <p>
      Get a guided tutorial on component-driven development at
      <a href="https://storybook.js.org/tutorials/" target="_blank" rel="noopener noreferrer">
        Storybook tutorials
      </a>
      . Read more in the
      <a href="https://storybook.js.org/docs" target="_blank" rel="noopener noreferrer"> docs </a>
      .
    </p>
    <div class="tip-wrapper">
      <span class="tip">Tip</span> Adjust the width of the canvas with the
      <svg width="10" height="10" viewBox="0 0 12 12" xmlns="http://www.w3.org/2000/svg">
        <g fill="none" fillRule="evenodd">
          <path
            d="M1.5 5.2h4.8c.3 0 .5.2.5.4v5.1c-.1.2-.3.3-.4.3H1.4a.5.5 0 01-.5-.4V5.7c0-.3.2-.5.5-.5zm0-2.1h6.9c.3 0 .5.2.5.4v7a.5.5 0 01-1 0V4H1.5a.5.5 0 010-1zm0-2.1h9c.3 0 .5.2.5.4v9.1a.5.5 0 01-1 0V2H1.5a.5.5 0 010-1zm4.3 5.2H2V10h3.8V6.2z"
            id="a"
            fill="#999"
          />
        </g>
      </svg>
      Viewports addon in the toolbar
    </div>
  </section>
</article>`,
  styleUrls: ['./page.css'],
})
export class PageComponent {
  //#region Properties
  /** Current user information */
  public user: User | null = null;
  //#endregion

  //#region Methods
  /** Handle user logout */
  public doLogout(): void {
    this.user = null;
  }
  /** Handle user login */
  public doLogin(): void {
    this.user = { name: 'Jane Doe' };
  }
  /** Handle account creation */
  public doCreateAccount(): void {
    this.user = { name: 'Jane Doe' };
  }
  //#endregion
}

