import { CommonModule } from '@angular/common';
import { Component, Input } from '@angular/core';
export type StatusType = 'good' | 'bad' | 'progress' | 'neutral';
export type StyleType = 'style1' | 'style2' | 'style3';
@Component({
  selector: 'app-status-chips',
  imports: [CommonModule],
  templateUrl: './status-chips.html',
  styleUrl: './status-chips.scss',
})
export class StatusChips {
  @Input() mode: 'single' | 'group' = 'group';
  @Input() label = 'Good 1';
  @Input() status: StatusType = 'good';
  @Input() selectedChip: string = '';
  @Input() styleType: StyleType = 'style1';
  @Input() activeStatus: StatusType | 'all' = 'all';
  @Input() goodLabelsText = 'Good 1,Good 2,Good 3';
  @Input() badLabelsText = 'Bad 1,Bad 2,Bad 3';
  @Input() progressLabelsText = 'Progress 1,Progress 2,Progress 3';
  @Input() neutralLabelsText = 'Neutral 1,Neutral 2,Neutral 3';
  readonly colorMap = {
    good: ['green1', 'green2', 'green3'],
    bad: ['red1', 'red2', 'red3'],
    progress: ['blue1', 'blue2', 'blue3'],
    neutral: ['gray1', 'gray2', 'gray3'],
  } as const;

  get goodLabels(): string[] {
    return this.parse(this.goodLabelsText);
  }

  get badLabels(): string[] {
    return this.parse(this.badLabelsText);
  }

  get progressLabels(): string[] {
    return this.parse(this.progressLabelsText);
  }

  get neutralLabels(): string[] {
    return this.parse(this.neutralLabelsText);
  }

  private parse(value: string): string[] {
    return value
      .split(',')
      .map(v => v.trim())
      .filter(Boolean);
  }

  getColor(status: StatusType, index: number): string {
    return this.colorMap[status][index % 3];
  }
  showChip(status: StatusType, index: number): boolean {
  if (!this.selectedChip) return true;
  return this.selectedChip === `${status}-${index}`;
}
}

import { CommonModule } from '@angular/common';
import { Component, HostListener, Input } from '@angular/core';
import { Accordion } from '../accordion/accordion';
import { InputField } from '../input-field/input-field';
import { StatusChips } from '../status-chips/status-chips';
import { Buttons } from "../buttons/buttons";
import { StatusBadge } from "../status-badge/status-badge";
export interface TableColumn {
  key: string;
  label: string;
}

export interface TableRow {
  id: number;
  link: string;
  date: string;
  v1: string;
  v2: string;
  status: string;
  expanded?: boolean;
  showDetails?: boolean;
  menuOpen?: boolean;
}
@Component({
  selector: 'app-table',
  imports: [CommonModule, Accordion, InputField, StatusChips, Buttons],
  templateUrl: './table.html',
  styleUrl: './table.scss',
})
export class Table {
  @Input()
  variant: 'header' | 'accordion' | 'buttons' | 'menu' = 'header';
  @Input() columns: TableColumn[] = [];
  @Input() headerColumns: TableColumn[] = [];
  @Input() rows: TableRow[] = [];
  @Input() showSearch = true;
  @Input() showSort = true;
  @Input() expandableHeader = false;
  @Input() headerExpanded = false;
  @Input()
  headerMode: 'default' | 'search-sort' = 'default';
  toggle(row: TableRow) {
    row.expanded = !row.expanded;
  }
  sortKey: string | null = null;
  sortDir: 'asc' | 'desc' = 'asc';
  onSort(key: string) {
    if (this.sortKey === key) {
      this.sortDir = this.sortDir === 'asc' ? 'desc' : 'asc';
    } else {
      this.sortKey = key;
      this.sortDir = 'asc';
    }
    this.sortRows();
  }
  sortRows() {
    if (!this.sortKey) return;
    const key = this.sortKey;
    this.rows = [...this.rows].sort((a: any, b: any) => {
      const v1 = a[key];
      const v2 = b[key];
      if (v1 < v2) return this.sortDir === 'asc' ? -1 : 1;
      if (v1 > v2) return this.sortDir === 'asc' ? 1 : -1;
      return 0;
    });
  }
  activeFilterKey: string | null = null;
  openFilter(key: string) {
    if (this.activeFilterKey === key) {
      this.activeFilterKey = null;
    } else {
      this.activeFilterKey = key; 
    }
  }
  getRowStatus(value: string): 'good' | 'bad' | 'progress' | 'neutral' {
    if (!value) return 'neutral';
    const v = value.toLowerCase();
    if (v.includes('good')) return 'good';
    if (v.includes('bad')) return 'bad';
    if (v.includes('progress')) return 'progress';
    return 'neutral';
  }
  toggleMenu(row: TableRow, event: Event) {
    event.stopPropagation();
    this.rows.forEach(r => {
      if (r !== row) r.menuOpen = false;
    });
    row.menuOpen = !row.menuOpen;
  }
  onEdit(row: TableRow) {
    console.log('Edit:', row);
    row.menuOpen = false;
  }
  onDelete(row: TableRow) {
    console.log('Delete:', row);
    row.menuOpen = false;
  }
  onTrack(row: TableRow) {
    console.log('Track:', row);
    row.menuOpen = false;
  }
  @HostListener('document:click')
  closeAllMenus() {
    this.rows.forEach(row => {
      row.menuOpen = false;
    });
  }
}

